// activities.ts — I/O and side effects go here
import type { ActivityOptions } from '@temporalio/activity';

export async function processPayment(orderId: string, amount: number): Promise<string> {
  // Call your payment provider SDK here
  const result = await stripe.charges.create({ amount, currency: 'usd' });
  return result.id;
}

export async function sendConfirmationEmail(orderId: string, chargeId: string): Promise<void> {
  await resend.emails.send({
    from: 'orders@acme.com',
    to: 'customer@example.com',
    subject: `Order ${orderId} confirmed`,
    html: `<p>Charge ID: ${chargeId}</p>`,
  });
}

// workflow.ts — must be fully deterministic; no I/O, no Date.now(), no Math.random()
import { proxyActivities, log } from '@temporalio/workflow';
import type * as activities from './activities';

const { processPayment, sendConfirmationEmail } = proxyActivities<typeof activities>({
  startToCloseTimeout: '30 seconds',
  retry: { maximumAttempts: 3 },
});

export async function orderWorkflow(orderId: string, amount: number): Promise<void> {
  log.info('Starting order workflow', { orderId });
  const chargeId = await processPayment(orderId, amount);
  await sendConfirmationEmail(orderId, chargeId);
  log.info('Order workflow complete', { orderId, chargeId });
}

// worker.ts — runs as a long-lived process alongside your app server
import { Worker } from '@temporalio/worker';
import * as activities from './activities';

const worker = await Worker.create({
  workflowsPath: require.resolve('./workflow'),
  activities,
  taskQueue: 'orders',
});
await worker.run();

// client-usage.ts — start the workflow from an API route
import { client } from './temporal-client';

const handle = await client.workflow.start(orderWorkflow, {
  taskQueue: 'orders',
  workflowId: `order-${orderId}`,
  args: [orderId, amount],
});
console.log('Workflow started:', handle.workflowId);

import {
  defineSignal,
  setHandler,
  condition,
  proxyActivities,
  sleep,
} from '@temporalio/workflow';
import type * as activities from './activities';

export const approveSignal = defineSignal<[{ approved: boolean; reviewerId: string }]>('approve');

const { requestHumanReview, processApprovedWithdrawal, notifyRejected } =
  proxyActivities<typeof activities>({ startToCloseTimeout: '10 seconds' });

export async function withdrawalApprovalWorkflow(
  withdrawalId: string,
  amount: number
): Promise<string> {
  let approvalResult: { approved: boolean; reviewerId: string } | null = null;

  // Register a signal handler — external callers can send this signal to the workflow
  setHandler(approveSignal, (result) => {
    approvalResult = result;
  });

  // Notify the review team that action is needed
  await requestHumanReview(withdrawalId, amount);

  // Wait up to 48 hours for a human to send the approval signal
  const approved = await condition(() => approvalResult !== null, '48 hours');

  if (!approved || !approvalResult?.approved) {
    await notifyRejected(withdrawalId);
    return 'rejected';
  }

  await processApprovedWithdrawal(withdrawalId, amount);
  return `approved-by-${approvalResult.reviewerId}`;
}
